let peerTableRefreshInFlight=false;
async function loadPeers(){bindPeerTabs();switchPeerTab(state.peerTab||'status');if(!can('peers.read')){stopPeerTableRefresh();document.getElementById('peerStatus').innerHTML='<div class="item">Permission required: peers.read</div>';document.getElementById('peersList').innerHTML='<div class="item">Permission required: peers.read</div>';document.getElementById('peerTopology').innerHTML='<div class="item">Permission required: peers.read</div>';document.getElementById('peerRelay').innerHTML='<div class="item">Permission required: peers.read</div>';return}setLoading('peerStatus','Loading peer status...');setLoading('peerTopology','Loading topology...');setLoading('peerRelay','Loading relay...');setLoading('peersList','Loading peers...');setLoading('peerDiscovery','Loading discovery jobs...');setLoading('peerInvites','Loading invitations...');const [d,jobsData,relayData]=await Promise.all([api('/api/peers',{local:true}),can('peers.connect')?api('/api/peers/discovery-jobs',{local:true}).catch(()=>({jobs:[]})):Promise.resolve({jobs:[]}),api('/api/peers/relay',{local:true}).catch(error=>({error:error.message||String(error)}))]);state.peers=d;state.peerRelay=relayData;state.peerDiscoveryJobs=jobsData.jobs||[];const inviteIds=new Set((d.invitations||[]).map(i=>i.id));Object.keys(state.peerInviteSecrets||{}).forEach(id=>{if(!inviteIds.has(id))delete state.peerInviteSecrets[id]});document.getElementById('peerStatus').innerHTML=peerStatusHtml(d);document.getElementById('peerTopology').innerHTML=renderPeerTopology(d);document.getElementById('peerRelay').innerHTML=renderPeerRelay(relayData);bindUiCopyButtons(document.getElementById('peerRelay'));renderPeersList(d);document.getElementById('peerDiscovery').innerHTML=peerDiscoveryJobsHtml(state.peerDiscoveryJobs);bindUiCopyButtons(document.getElementById('peerDiscovery'));document.getElementById('peerInvites').innerHTML=renderPeerInvitesTable(d.invitations||[]);ensureGlobalPeerSessionsPanel();bindPeerButtons();if(typeof applyHeaderPeerSnapshot==='function'&&state.localBootstrap){applyHeaderPeerSnapshot(d,state.localBootstrap);renderHeaderTargetMenu(state.snapshot)}applyPermissions();startPeerTableRefresh()}
function renderPeersList(d){const target=document.getElementById('peersList');if(!target)return;target.innerHTML=renderPeersTable(d?.peers||[]);startSessionAgeCounter()}
async function refreshPeersTable(){if(state.currentPage!=='peers'){stopPeerTableRefresh();return}if(peerTableRefreshInFlight||!can('peers.read')||document.hidden)return;peerTableRefreshInFlight=true;try{const d=await api('/api/peers',{local:true});state.peers=d;renderPeersList(d);bindPeerButtons();if(typeof applyHeaderPeerSnapshot==='function'&&state.localBootstrap){applyHeaderPeerSnapshot(d,state.localBootstrap);renderHeaderTargetMenu(state.snapshot)}applyPermissions()}finally{peerTableRefreshInFlight=false}}
function startPeerTableRefresh(){if(state.currentPage!=='peers'||state.peerRefreshTimer)return;state.peerRefreshTimer=setInterval(()=>{if(state.currentPage!=='peers'){stopPeerTableRefresh();return}safe(refreshPeersTable)},5000)}
function stopPeerTableRefresh(){if(state.peerRefreshTimer)clearInterval(state.peerRefreshTimer);state.peerRefreshTimer=null}
function switchPeerTab(tab){state.peerTab=tab||'status';document.querySelectorAll('[data-peer-tab]').forEach(b=>{const active=b.dataset.peerTab===state.peerTab;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false');b.tabIndex=active?0:-1});document.querySelectorAll('[data-peer-tab-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.peerTabPanel===state.peerTab))}
function bindPeerTabs(){document.querySelectorAll('[data-peer-tab]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='true';b.onclick=()=>switchPeerTab(b.dataset.peerTab)})}
function openPeerAddDialog(){const publicUrl=state.peers?.enabled?state.peers?.listenUrl||'':'';adminDialog('Add peer','<label>Peer URL<input id="dlgPeerAddUrl" placeholder="https://host:31979"></label><label>Pairing code<input id="dlgPeerAddCode"></label><label>Name<input id="dlgPeerAddName" placeholder="optional local label"></label><label>Group<input id="dlgPeerAddGroup" placeholder="LAN, Servers, Workstations"></label><label>Public URL for this node<input id="dlgPeerAddPublicUrl" placeholder="optional" value="'+attr(publicUrl)+'"></label>',async()=>{const r=await api('/api/peers/pair',{method:'POST',body:JSON.stringify({url:val('dlgPeerAddUrl'),code:val('dlgPeerAddCode'),name:val('dlgPeerAddName')||undefined,publicUrl:val('dlgPeerAddPublicUrl')||undefined}),local:true});if(val('dlgPeerAddGroup')&&r.peer?.id)await api('/api/peers/'+encodeURIComponent(r.peer.id),{method:'PATCH',body:JSON.stringify({group:val('dlgPeerAddGroup')}),local:true});toast('Added peer '+(r.peer?.name||''));await loadPeers()})}
function openPeerSyncDialog(){const peers=(state.peers?.peers||[]).filter(p=>p.enabled);if(!peers.length){toast('Add at least one peer first.');return}const options=peers.map(p=>'<option value="'+attr(p.id)+'">'+esc(p.name||p.id)+'</option>').join('');adminDialog('Sync peers','<label class="full-span">Source peer<select id="dlgPeerSyncSource">'+options+'</select></label><div class="full-span"><p>Load peers known by the selected source peer, then choose which ones should be paired with this node. NordRelay creates a fresh pairing instead of copying peer secrets.</p><div class="row"><button type="button" id="loadPeerSyncCandidatesBtn" class="secondary">Load peers</button></div><div id="peerSyncCandidates">'+uiEmpty('Load peers from a source peer to start.')+'</div></div>',async()=>{const selected=[...document.querySelectorAll<HTMLInputElement>('[data-peer-sync-choice]:checked')].map(input=>input.value);if(!selected.length)throw new Error('Select at least one peer to sync.');const r=await api('/api/peers/sync',{method:'POST',local:true,body:JSON.stringify({sourcePeerId:val('dlgPeerSyncSource'),candidateNodeIds:selected})});toast('Peer sync completed: '+(r.created||0)+' created, '+(r.skipped||0)+' skipped, '+(r.failed||0)+' failed',{duration:9000});await loadPeers()},{submitText:'Import selected',reloadAccess:false});document.getElementById('loadPeerSyncCandidatesBtn').onclick=()=>safe(loadPeerSyncCandidates);document.getElementById('dlgPeerSyncSource').onchange=()=>{document.getElementById('peerSyncCandidates').innerHTML=uiEmpty('Load peers from this source peer to refresh candidates.');document.getElementById('adminDialogSubmit').disabled=true};document.getElementById('adminDialogSubmit').disabled=true}
async function loadPeerSyncCandidates(){const source=val('dlgPeerSyncSource');const target=document.getElementById('peerSyncCandidates');target.innerHTML=loadingHtml('Loading peer candidates...');const d=await api('/api/peers/'+encodeURIComponent(source)+'/sync-candidates',{local:true});target.innerHTML=renderPeerSyncCandidatesTable(d.candidates||[]);const submit=document.getElementById('adminDialogSubmit');if(submit)submit.disabled=!(d.candidates||[]).some(c=>c.importable)}
function renderPeerSyncCandidatesTable(candidates){if(!candidates.length)return uiEmpty('The selected source peer has no peers to sync.');return '<div class="data-table-wrap"><table class="data-table peer-sync-table"><thead><tr><th></th><th>Name</th><th>Status</th><th>URL</th><th>Rights</th><th>Agents</th><th>Workspaces</th><th>Reason</th></tr></thead><tbody>'+candidates.map(peerSyncCandidateRow).join('')+'</tbody></table></div>'}
function peerSyncCandidateRow(c){const p=c.peer||{};const status=c.importable?'<span class="adapter-status enabled">ready</span>':c.alreadyExists?'<span class="adapter-status planned">added</span>':'<span class="adapter-status disabled">blocked</span>';const checkbox='<input type="checkbox" data-peer-sync-choice value="'+attr(p.nodeId||'')+'" '+(c.importable?'':'disabled')+'>';return '<tr>'+peerCell('Select',checkbox)+peerCell('Name','<span class="truncate-cell" title="'+attr(p.name||'-')+'">'+esc(short(p.name||'-',120))+'</span>','primary-cell')+peerCell('Status',status,'status-cell')+peerCell('URL','<span class="truncate-cell" title="'+attr(p.url||'-')+'">'+esc(short(p.url||'-',140))+'</span>')+peerCell('Rights','<span class="truncate-cell" title="'+attr((p.scopes||[]).join(', ')||'-')+'">'+esc(short((p.scopes||[]).join(', ')||'-',120))+'</span>')+peerCell('Agents','<span class="truncate-cell" title="'+attr((p.allowedAgents||[]).join(', ')||'all')+'">'+esc(short((p.allowedAgents||[]).join(', ')||'all',90))+'</span>')+peerCell('Workspaces','<span class="truncate-cell" title="'+attr((p.allowedWorkspaceRoots||[]).join(', ')||'all')+'">'+esc(short((p.allowedWorkspaceRoots||[]).join(', ')||'all',120))+'</span>')+peerCell('Reason','<span class="truncate-cell" title="'+attr(c.reason||'')+'">'+esc(short(c.reason||'-',120))+'</span>')+'</tr>'}
