document.addEventListener('click',e=>{const b=e.target.closest?.('[data-peer-repin]');if(!b)return;safe(async()=>{if(!can('peers.write')){toast('Permission required: peers.write');return}if(confirm('Re-pin TLS fingerprint for this peer?')){const r=await api('/api/peers/'+encodeURIComponent(b.dataset.peerRepin)+'/repin',{method:'POST',local:true});toast('TLS fingerprint updated: '+(r.peer?.tlsFingerprint||'-'),{duration:8000});loadPeers()}})});
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-peer-rotate]');if(!b)return;safe(async()=>{if(!can('peers.write')){toast('Permission required: peers.write');return}if(confirm('Create a new pairing invite for this peer using the current scopes?')){const r=await api('/api/peers/'+encodeURIComponent(b.dataset.peerRotate)+'/rotate',{method:'POST',body:JSON.stringify({expiresMinutes:10}),local:true});if(r.invitation?.id)state.peerInviteSecrets[r.invitation.id]={code:r.code||'',command:r.command||''};toast('Rotation invite created. Pairing details are shown under Open invitations.',{duration:8000});loadPeers()}})});
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-peer-debug]');if(!b)return;safe(()=>openPeerDebugDialog(b.dataset.peerDebug))});
function ensureGlobalPeerSessionsPanel(){const button=document.getElementById('loadGlobalPeerSessionsBtn');if(button&&!button.dataset.bound){button.dataset.bound='true';button.onclick=()=>safe(loadGlobalPeerSessions)}if(document.getElementById('globalPeerSessionsPanel'))return;const anchor=document.getElementById('peersList');if(!anchor)return;anchor.insertAdjacentHTML('afterend','<div id="globalPeerSessionsPanel" class="list"><div class="item"><div class="row"><input id="globalPeerSessionSearch" placeholder="Search sessions across peers"><button id="loadGlobalPeerSessionsBtn">Load global sessions</button></div><div id="globalPeerSessionsList"></div></div></div>');document.getElementById('loadGlobalPeerSessionsBtn').onclick=()=>safe(loadGlobalPeerSessions)}
async function loadGlobalPeerSessions(){const target=document.getElementById('globalPeerSessionsList');target.innerHTML=loadingHtml('Loading global sessions...');const q=document.getElementById('globalPeerSessionSearch').value||'';const d=await api('/api/peers/global-sessions',{local:true,query:{query:q,agent:state.snapshot?.session?.agentId||undefined,limit:50}});target.innerHTML=renderGlobalPeerSessionsTable(d.targets||[]);bindUiCopyButtons(target)}
function renderGlobalPeerSessionsTable(targets){const rows=[];(targets||[]).forEach(t=>{if(!t.ok){rows.push('<tr>'+peerCell('Peer','<span class="truncate-cell" title="'+attr(t.peerName||t.peerId||'-')+'">'+esc(t.peerName||t.peerId||'-')+'</span>','primary-cell')+peerCell('Status','<span class="adapter-status disabled">error</span>','status-cell')+peerCell('Thread','-')+peerCell('Workspace','-')+peerCell('Updated','-')+peerCell('Detail','<span class="truncate-cell error" title="'+attr(t.error||'failed')+'">'+esc(short(t.error||'failed',180))+'</span>')+'</tr>');return}const sessions=t.data?.sessions||[];if(!sessions.length){rows.push('<tr>'+peerCell('Peer','<span class="truncate-cell" title="'+attr(t.peerName||t.peerId||'-')+'">'+esc(t.peerName||t.peerId||'-')+'</span>','primary-cell')+peerCell('Status','<span class="adapter-status enabled">ok</span>','status-cell')+peerCell('Thread','-')+peerCell('Workspace','No sessions')+peerCell('Updated','-')+peerCell('Detail','-')+'</tr>');return}sessions.slice(0,12).forEach(s=>{rows.push('<tr>'+peerCell('Peer','<span class="truncate-cell" title="'+attr(t.peerName+' ('+t.peerId+')')+'">'+esc(t.peerName||t.peerId||'-')+'</span>','primary-cell')+peerCell('Status','<span class="adapter-status enabled">ok</span>','status-cell')+peerCell('Thread',s.id?uiCopyButton(s.id,'Thread ID copied'):'-')+peerCell('Workspace','<span class="truncate-cell" title="'+attr(s.cwd||'-')+'">'+esc(short(s.cwd||'-',140))+'</span>')+peerCell('Updated',esc(fmtDate(s.updatedAt)))+peerCell('Detail','<span class="truncate-cell" title="'+attr(s.title||s.summary||'')+'">'+esc(short(s.title||s.summary||'-',160))+'</span>')+'</tr>')})});if(!rows.length)return uiEmpty('No peer sessions found.');return '<div class="data-table-wrap"><table class="data-table global-peer-sessions-table"><thead><tr><th>Peer</th><th>Status</th><th>Thread</th><th>Workspace</th><th>Updated</th><th>Detail</th></tr></thead><tbody>'+rows.join('')+'</tbody></table></div>'}
function peerCell(label,html,cls=''){return '<td data-label="'+attr(label)+'"'+(cls?' class="'+cls+'"':'')+'>'+html+'</td>'}
function peerHealthSummary(p){const h=p.healthHistory||[];if(!h.length)return{uptime:'-',avg:'-',last:'unchecked',error:p.lastError||''};const online=h.filter(x=>x.status==='online');const lat=online.map(x=>Number(x.latencyMs)).filter(Number.isFinite);return{uptime:Math.round((online.length/h.length)*100)+'%',avg:lat.length?Math.round(lat.reduce((a,b)=>a+b,0)/lat.length)+'ms':'-',last:h[h.length-1]?.status||'unchecked',error:p.lastError||h.slice().reverse().find(x=>x.error)?.error||''}}
function peerName(id){return (state.peers?.peers||[]).find(p=>p.id===id)?.name||id}
function relayStatusBadge(status){return '<span class="adapter-status '+(status==='ok'||status==='completed'?'enabled':status==='error'||status==='failed'?'disabled':'planned')+'">'+esc(status)+'</span>'}
function peerRelaySummaryRows(d){const q=d.queue||{};const outbound=d.outbound||{};return [['Outbound relay',d.enabled?'enabled':'disabled'],['Allowed peers',(d.allowedPeerIds||[]).join(', ')||'all configured outbound peers'],['Pending requests',(q.pending||[]).length],['In flight',(q.inFlight||[]).length],['Completed retained',(q.completed||[]).length],['Outbound pollers',(outbound.peers||[]).length],['Updated',fmtDate(d.updatedAt)]]}
function renderPeerRelaySummary(d){return '<h3 class="table-section-title">Relay status</h3><div class="data-table-wrap"><table class="data-table peer-relay-summary-table"><thead><tr><th>Metric</th><th>Value</th></tr></thead><tbody>'+peerRelaySummaryRows(d).map(row=>'<tr>'+peerCell('Metric',esc(row[0]),'primary-cell')+peerCell('Value','<span class="truncate-cell" title="'+attr(row[1]??'-')+'">'+esc(row[1]??'-')+'</span>')+'</tr>').join('')+'</tbody></table></div>'}
function relayRequestRow(r){const peer=peerName(r.peerId);const detail=[r.requestType,r.path,r.contextKey].filter(Boolean).join(' | ')||'-';const actions='<div class="data-table-actions"><button class="danger" data-peer-relay-cancel="'+attr(r.id)+'" data-peer-id="'+attr(r.peerId)+'"'+disabledAttr('peers.write')+'>Cancel</button></div>';return '<tr>'+peerCell('State',relayStatusBadge(r.state),'status-cell')+peerCell('Peer','<span class="truncate-cell" title="'+attr(peer)+'">'+esc(short(peer,90))+'</span>','primary-cell')+peerCell('Request','<span class="truncate-cell" title="'+attr(detail)+'">'+esc(short(detail,180))+'</span>')+peerCell('Actor','<span class="truncate-cell" title="'+attr(r.actorLabel||'-')+'">'+esc(short(r.actorLabel||'-',90))+'</span>')+peerCell('Age',esc(fmtDuration(r.ageMs)))+peerCell('Expires',esc(fmtDuration(Math.max(0,r.expiresInMs||0))))+peerCell('ID',uiCopyButton(r.id,'Relay request ID copied'))+peerCell('Actions',actions,'actions-cell')+'</tr>'}
function renderRelayRequestsTable(items){if(!items.length)return uiEmpty('No queued or in-flight relay requests.');return '<div class="data-table-wrap"><table class="data-table peer-relay-table"><thead><tr><th>State</th><th>Peer</th><th>Request</th><th>Actor</th><th>Age</th><th>Expires in</th><th>ID</th><th class="actions-heading">Actions</th></tr></thead><tbody>'+items.map(relayRequestRow).join('')+'</tbody></table></div>'}
function relayOutboundRow(p){const peer=peerName(p.peerId);const detail=p.lastError||('idle '+(p.idlePolls||0)+' / completed '+(p.completedRequests||0));return '<tr>'+peerCell('Peer','<span class="truncate-cell" title="'+attr(peer)+'">'+esc(short(peer,100))+'</span>','primary-cell')+peerCell('State',relayStatusBadge(p.enabled&&p.allowed&&!p.lastError?'ok':p.lastError?'error':'paused'),'status-cell')+peerCell('Failures',esc(String(p.failures||0)))+peerCell('Idle',esc(String(p.idlePolls||0)))+peerCell('Last poll',esc(fmtDate(p.lastPollAt)))+peerCell('Next poll',esc(fmtDate(p.nextPollAt)))+peerCell('Detail','<span class="truncate-cell '+(p.lastError?'error':'')+'" title="'+attr(detail)+'">'+esc(short(detail,200))+'</span>')+'</tr>'}
function renderRelayOutboundTable(peers){if(!peers.length)return uiEmpty('No outbound relay pollers observed.');return '<div class="data-table-wrap"><table class="data-table peer-relay-outbound-table"><thead><tr><th>Peer</th><th>State</th><th>Failures</th><th>Idle</th><th>Last poll</th><th>Next poll</th><th>Detail</th></tr></thead><tbody>'+peers.map(relayOutboundRow).join('')+'</tbody></table></div>'}
function relayCompletedRow(r){return '<tr>'+peerCell('Peer','<span class="truncate-cell" title="'+attr(peerName(r.peerId))+'">'+esc(short(peerName(r.peerId),100))+'</span>','primary-cell')+peerCell('Status',relayStatusBadge(r.ok?'completed':'failed'),'status-cell')+peerCell('Resolved',esc(fmtDate(r.resolvedAt)))+peerCell('ID',uiCopyButton(r.id,'Relay request ID copied'))+peerCell('Error','<span class="truncate-cell '+(r.error?'error':'')+'" title="'+attr(r.error||'-')+'">'+esc(short(r.error||'-',200))+'</span>')+'</tr>'}
function renderRelayCompletedTable(items){if(!items.length)return uiEmpty('No completed relay requests retained.');return '<div class="data-table-wrap"><table class="data-table peer-relay-completed-table"><thead><tr><th>Peer</th><th>Status</th><th>Resolved</th><th>ID</th><th>Error</th></tr></thead><tbody>'+items.slice(0,50).map(relayCompletedRow).join('')+'</tbody></table></div>'}
function renderPeerRelay(d){if(!d)return uiEmpty('Relay status not loaded.');if(d.error)return '<div class="item warning"><strong>Relay status unavailable</strong><small>'+esc(d.error)+'</small></div>';const q=d.queue||{};return renderPeerRelaySummary(d)+'<h3 class="table-section-title">Pending and in-flight</h3>'+renderRelayRequestsTable([...(q.pending||[]),...(q.inFlight||[])])+'<h3 class="table-section-title">Outbound pollers</h3>'+renderRelayOutboundTable(d.outbound?.peers||[])+'<h3 class="table-section-title">Completed</h3>'+renderRelayCompletedTable(q.completed||[])}
function peerTopologyNodeHtml(label,meta,cls=''){return '<div class="peer-topology-node '+cls+'"><strong>'+esc(label)+'</strong>'+meta.map(item=>'<small>'+item+'</small>').join('')+'</div>'}
function renderPeerTopology(d){const peers=d.peers||[];const localMeta=['Node '+esc(short(d.identity?.nodeId||'-',32)),'Listen '+esc(d.listenUrl||'-'),d.readiness?.localListening?'listening':'not listening'];const rows=peers.map(p=>{const health=peerHealthSummary(p);const relay=p.url?'direct':'outbound relay';const trust=p.trustStatus||'trusted';return '<tr>'+peerCell('Peer','<span class="truncate-cell" title="'+attr(p.name)+'">'+esc(p.name)+'</span>','primary-cell')+peerCell('Link','<span class="adapter-status '+(p.url?'enabled':'planned')+'">'+esc(relay)+'</span>','status-cell')+peerCell('Direction',esc(p.direction||'-'))+peerCell('Trust','<span class="adapter-status '+(trust==='trusted'?'enabled':trust==='tls-unpinned'?'planned':'disabled')+'">'+esc(trust)+'</span>','status-cell')+peerCell('Uptime',esc(health.uptime))+' '+peerCell('Avg latency',esc(health.avg))+peerCell('Last',esc(health.last))+peerCell('Detail','<span class="truncate-cell" title="'+attr(health.error||p.url||'Polling relay requests when outbound relay is enabled on the remote node.')+'">'+esc(short(health.error||p.url||'No direct URL. Uses outbound relay polling.',160))+'</span>')+'</tr>'}).join('');const table=rows?'<div class="data-table-wrap"><table class="data-table peer-topology-table"><thead><tr><th>Peer</th><th>Link</th><th>Direction</th><th>Trust</th><th>Uptime</th><th>Avg latency</th><th>Last</th><th>Detail</th></tr></thead><tbody>'+rows+'</tbody></table></div>':uiEmpty('No peers configured.');const cards='<div class="peer-topology-map">'+peerTopologyNodeHtml('This node',localMeta,'local')+peers.map(p=>{const h=peerHealthSummary(p);const meta=['via '+esc(p.url?'direct URL':'outbound relay'),esc((p.remoteStatus||h.last)+(p.lastLatencyMs!==undefined?' / '+p.lastLatencyMs+'ms':'')),esc('TLS '+(p.tlsFingerprint?'pinned':'un-pinned'))];return peerTopologyNodeHtml(p.name,meta,p.lastError?'warn':'')}).join('')+'</div>';return cards+table}
function peerStatusHtml(d){const r=d.readiness||{};const rows=[['Peer server',d.enabled?'enabled':'disabled'],['Listen URL',d.listenUrl],['Bind',[(r.bindHost||'-'),(r.port||'')].filter(Boolean).join(':')],['Local port',r.localListening?'listening':'not listening'],['TLS',r.tlsEnabled?'enabled':'disabled'],['TLS expires',r.tlsExpiresAt?fmtDate(r.tlsExpiresAt):'-'],['Require TLS',d.requireTls?'yes':'no'],['Node ID',d.identity?.nodeId],['Fingerprint',d.identity?.fingerprint]];const command=r.manualCheckCommand||('nordrelay peer check '+(d.listenUrl||''));return '<h3 class="table-section-title">Local peer identity</h3><div class="data-table-wrap"><table class="data-table peer-status-table"><thead><tr><th>Metric</th><th>Value</th></tr></thead><tbody>'+rows.map(row=>'<tr>'+peerCell('Metric',esc(row[0]),'primary-cell')+peerCell('Value','<span class="truncate-cell" title="'+attr(row[1]??'-')+'">'+esc(row[1]??'-')+'</span>')+'</tr>').join('')+'</tbody></table></div>'+peerWarningsHtml(r.warnings||[],'Peer readiness')+'<div class="peer-invite-details"><small>Manual reachability check</small><button type="button" class="copy-id peer-invite-command" data-peer-invite-copy="'+attr(command)+'" data-peer-invite-copy-label="Peer check command copied">'+esc(command)+'</button><small>Run this on another machine to verify LAN, port-forward, or firewall reachability.</small></div><div class="row"><button id="checkPeerReachabilityBtn" class="secondary"'+disabledAttr('peers.connect')+'>Check local endpoint</button></div><div id="peerProbeResult">'+peerProbeResultHtml(state.peerProbeResult)+'</div>'}
async function discoverPeers(){if(!can('peers.connect')){toast('Permission required: peers.connect');return}const target=document.getElementById('peerDiscovery');target.innerHTML=loadingHtml('Starting LAN peer discovery...');const body={targets:csvToList(val('peerDiscoveryTargets')),maxHosts:Number(val('peerDiscoveryMaxHosts')||512),concurrency:Number(val('peerDiscoveryConcurrency')||32)};const data=await api('/api/peers/discovery-jobs',{method:'POST',body:JSON.stringify(body),local:true});state.activePeerDiscoveryJobId=data.job?.id;await pollPeerDiscoveryJob(data.job?.id)}
async function pollPeerDiscoveryJob(id){if(!id)return;const target=document.getElementById('peerDiscovery');for(;;){const data=await api('/api/peers/discovery-jobs/'+encodeURIComponent(id),{local:true});const job=data.job;if(!job){target.innerHTML=uiEmpty('Discovery job not found.');return}target.innerHTML=peerDiscoveryJobsHtml([job]);bindUiCopyButtons(target);applyPermissions();if(!['queued','running'].includes(job.status))break;await new Promise(r=>setTimeout(r,1000))}}
async function cancelPeerDiscovery(){const id=state.activePeerDiscoveryJobId;if(!id){toast('No active discovery job');return}const data=await api('/api/peers/discovery-jobs/'+encodeURIComponent(id)+'/cancel',{method:'POST',local:true});if(data.job){document.getElementById('peerDiscovery').innerHTML=peerDiscoveryJobsHtml([data.job])}toast('Discovery cancelled')}
async function exportPeerIdentity(){if(!can('peers.write')){toast('Permission required: peers.write');return}const data=await api('/api/peers/identity/backup',{local:true});downloadJson('nordrelay-peer-identity-backup.json',data.backup);toast('Peer identity backup exported')}
async function restorePeerIdentity(){if(!can('peers.write')){toast('Permission required: peers.write');return}const text=prompt('Paste peer identity backup JSON');if(!text)return;const backup=JSON.parse(text);await api('/api/peers/identity/restore',{method:'POST',body:JSON.stringify({backup}),local:true});toast('Peer identity restored. Restart peer server to use it.');await loadPeers()}
function downloadJson(name,value){const blob=new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
function peerDiscoveryJobsHtml(jobs){const list=(jobs||[]).slice(0,5);if(!list.length)return uiEmpty('No LAN discovery jobs yet.');return '<div class="data-table-wrap"><table class="data-table peer-discovery-table"><thead><tr><th>Job</th><th>Status</th><th>Progress</th><th>Targets</th><th>Started</th><th>Completed</th><th>Found</th></tr></thead><tbody>'+list.map(peerDiscoveryJobRow).join('')+'</tbody></table></div>'+list.map(peerDiscoveryJobDetails).join('')}
function peerDiscoveryJobRow(job){const progress=job.total?Math.round((job.scanned/job.total)*100):0;const status='<span class="adapter-status '+(job.status==='completed'?'enabled':job.status==='failed'?'disabled':'planned')+'">'+esc(job.status)+'</span>';return '<tr>'+peerCell('Job','<span class="truncate-cell" title="'+attr(job.id)+'">'+esc(job.id)+'</span>','primary-cell')+peerCell('Status',status,'status-cell')+peerCell('Progress',esc(job.scanned+' / '+job.total+' ('+progress+'%)'))+peerCell('Targets','<span class="truncate-cell" title="'+attr((job.options?.targets||[]).join(', ')||'local LAN + mDNS')+'">'+esc(short((job.options?.targets||[]).join(', ')||'local LAN + mDNS',120))+'</span>')+peerCell('Started',esc(fmtDate(job.startedAt)))+peerCell('Completed',esc(fmtDate(job.completedAt)))+peerCell('Found',esc(String((job.candidates||[]).length)))+'</tr>'}
function peerDiscoveryJobDetails(job){return '<div class="peer-table-detail">'+peerDiscoveryHtml(job)+'<details class="peer-health-history"><summary>Discovery log ('+(job.log||[]).length+')</summary>'+(job.log||[]).slice(-30).map(line=>'<small>'+esc(line)+'</small>').join('')+'</details></div>'}
function peerDiscoveryHtml(data){const warnings=(data.warnings||[]).length?peerWarningsHtml(data.warnings,'Discovery warning'):'';const candidates=data.candidates||[];if(!candidates.length)return warnings+uiEmpty('No LAN peers found. Scanned '+(data.scanned||0)+' endpoint candidates.');return warnings+'<div class="data-table-wrap"><table class="data-table peer-candidates-table"><thead><tr><th>Name</th><th>URL</th><th>Node</th><th>Fingerprint</th><th>TLS</th><th>Latency</th><th class="actions-heading">Command</th></tr></thead><tbody>'+candidates.map(c=>{const command='nordrelay peer add '+c.url+' --code <pairing-code>';return '<tr>'+peerCell('Name','<span class="truncate-cell" title="'+attr(c.name||c.host||'-')+'">'+esc(c.name||c.host||'-')+'</span>','primary-cell')+peerCell('URL','<span class="truncate-cell" title="'+attr(c.url||'-')+'">'+esc(c.url||'-')+'</span>')+peerCell('Node','<span class="truncate-cell" title="'+attr(c.nodeId||'-')+'">'+esc(short(c.nodeId||'-',80))+'</span>')+peerCell('Fingerprint','<span class="truncate-cell" title="'+attr(c.fingerprint||'-')+'">'+esc(short(c.fingerprint||'-',80))+'</span>')+peerCell('TLS','<span class="truncate-cell" title="'+attr(c.tlsFingerprint||'-')+'">'+esc(short(c.tlsFingerprint||'-',80))+'</span>')+peerCell('Latency',esc(c.latencyMs!==undefined?c.latencyMs+'ms':'-'))+peerCell('Command','<div class="data-table-actions">'+uiCopyButton(command,'Peer add command copied','copy-id peer-invite-command')+'</div>','actions-cell')+'</tr>'}).join('')+'</tbody></table></div>'}
function peerWarningsHtml(warnings,title){return (warnings||[]).length?'<div class="peer-warning full-span"><strong>'+esc(title||'Warning')+'</strong>'+warnings.map(w=>'<small>'+esc(w)+'</small>').join('')+'</div>':''}
function peerProbeResultHtml(result){if(!result)return'';const probe=result.probe||{};const label=result.type==='remote'?'Remote probe from '+(result.peerName||result.peerId||'peer'):'Local endpoint check';return '<div class="peer-probe-result '+(probe.ok?'ok':'warn')+'"><strong>'+esc(label)+' <span class="adapter-status '+(probe.ok?'enabled':'planned')+'">'+esc(probe.status||'unknown')+'</span></strong><small>'+esc('URL: '+(probe.url||result.readiness?.listenUrl||'-'))+'</small>'+(probe.latencyMs!==undefined?'<small>'+esc('Latency: '+probe.latencyMs+'ms')+'</small>':'')+(probe.statusCode!==undefined?'<small>'+esc('HTTP: '+probe.statusCode)+'</small>':'')+(probe.tlsFingerprint?'<small>'+esc('TLS fingerprint: '+probe.tlsFingerprint)+'</small>':'')+'<small>'+esc(probe.detail||'')+'</small></div>'}
function peerInviteDetails(i){const details=state.peerInviteSecrets?.[i.id];if(!details)return'';return '<div class="peer-invite-inline-details"><small>Pairing code</small><button type="button" class="copy-id peer-invite-code" data-peer-invite-copy="'+attr(details.code||'')+'" data-peer-invite-copy-label="Pairing code copied">'+esc(details.code||'')+'</button><small>Command</small><button type="button" class="copy-id peer-invite-command" data-peer-invite-copy="'+attr(details.command||'')+'" data-peer-invite-copy-label="Peer add command copied">'+esc(details.command||'')+'</button></div>'}
function renderPeerInvitesTable(invites){const readiness=state.peers?.readiness;if(!invites.length)return uiEmpty('No open invitations.');const warning=(readiness?.warnings||[]).length?peerWarningsHtml(readiness.warnings,'Pairing warning'):'';return warning+'<div class="data-table-wrap"><table class="data-table peer-invites-table"><thead><tr><th>Name</th><th>Status</th><th>Group</th><th>Expires</th><th>Scopes</th><th>Agents</th><th>Used</th><th class="actions-heading">Actions</th></tr></thead><tbody>'+invites.map(peerInviteRow).join('')+'</tbody></table></div>'}
function peerInviteRow(i){const open=new Date(i.expiresAt)>new Date()&&!i.usedAt;const details=peerInviteDetails(i);const actions=open?'<div class="data-table-actions">'+(details||'')+'<button class="danger" data-peer-invite-delete="'+attr(i.id)+'"'+disabledAttr('peers.write')+'>Delete</button></div>':'-';return '<tr>'+peerCell('Name','<span class="truncate-cell" title="'+attr(i.name)+'">'+esc(i.name)+'</span>','primary-cell')+peerCell('Status','<span class="chip">'+esc(open?'open':'closed')+'</span>','status-cell')+peerCell('Group','<span class="truncate-cell" title="'+attr(i.group||'-')+'">'+esc(i.group||'-')+'</span>')+peerCell('Expires',esc(fmtDate(i.expiresAt)))+peerCell('Scopes','<span class="truncate-cell" title="'+attr((i.scopes||[]).join(', '))+'">'+esc(short((i.scopes||[]).join(', ')||'-',140))+'</span>')+peerCell('Agents','<span class="truncate-cell" title="'+attr((i.allowedAgents||[]).join(', ')||'all')+'">'+esc((i.allowedAgents||[]).join(', ')||'all')+'</span>')+peerCell('Used',i.usedAt?'<span class="truncate-cell" title="'+attr(fmtDate(i.usedAt)+' by '+(i.usedByNodeId||'-'))+'">'+esc(short(fmtDate(i.usedAt)+' by '+(i.usedByNodeId||'-'),100))+'</span>':'-')+peerCell('Actions',actions,'actions-cell')+'</tr>'}
function renderPeersTable(peers){if(!peers.length)return uiEmpty('No peers configured.');return '<div class="data-table-wrap"><table class="data-table peers-table"><thead><tr><th>Name</th><th>Status</th><th>Trust</th><th>URL</th><th>Access</th><th>Health</th><th>Version</th><th>Last seen</th><th class="actions-heading">Actions</th></tr></thead><tbody>'+peers.map(peerRow).join('')+'</tbody></table></div>'}
let tableActionMenuListenersBound=false;
function resetTableActionMenu(menu:HTMLDetailsElement){const list=menu.querySelector<HTMLElement>('.table-action-menu-list');menu.classList.remove('is-floating');if(list){list.style.left='';list.style.top='';list.style.right='';list.style.visibility=''}}
function closeTableActionMenus(except?:HTMLDetailsElement){document.querySelectorAll<HTMLDetailsElement>('.table-action-menu[open]').forEach(menu=>{if(menu===except)return;menu.open=false;resetTableActionMenu(menu)})}
function positionTableActionMenu(menu:HTMLDetailsElement){const summary=menu.querySelector<HTMLElement>('summary');const list=menu.querySelector<HTMLElement>('.table-action-menu-list');if(!menu.open||!summary||!list)return;const margin=8;const gap=menu.classList.contains('peer-action-menu')?8:6;menu.classList.add('is-floating');list.style.visibility='hidden';list.style.left='0px';list.style.top='0px';list.style.right='auto';const buttonRect=summary.getBoundingClientRect();const listRect=list.getBoundingClientRect();const width=Math.max(listRect.width,menu.classList.contains('peer-action-menu')?220:150);const height=listRect.height;const maxLeft=Math.max(margin,window.innerWidth-width-margin);let left=Math.min(Math.max(margin,buttonRect.right-width),maxLeft);let top=buttonRect.bottom+gap;if(top+height>window.innerHeight-margin&&buttonRect.top-height-gap>margin)top=buttonRect.top-height-gap;else top=Math.min(top,Math.max(margin,window.innerHeight-height-margin));list.style.left=Math.round(left)+'px';list.style.top=Math.round(Math.max(margin,top))+'px';list.style.visibility=''}
function positionOpenTableActionMenus(){document.querySelectorAll<HTMLDetailsElement>('.table-action-menu[open]').forEach(menu=>positionTableActionMenu(menu))}
function bindTableActionMenus(root:Document|Element=document){root.querySelectorAll<HTMLDetailsElement>('.table-action-menu').forEach(menu=>{if(menu.dataset.floatingBound)return;menu.dataset.floatingBound='true';menu.addEventListener('toggle',()=>{if(menu.open){closeTableActionMenus(menu);positionTableActionMenu(menu)}else resetTableActionMenu(menu)});menu.addEventListener('click',event=>{const target=event.target instanceof Element?event.target:null;if(target?.closest('button'))setTimeout(()=>{menu.open=false;resetTableActionMenu(menu)},0)})});if(tableActionMenuListenersBound)return;tableActionMenuListenersBound=true;document.addEventListener('click',event=>{const target=event.target instanceof Element?event.target:null;if(target?.closest('.table-action-menu'))return;closeTableActionMenus()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeTableActionMenus()});window.addEventListener('resize',positionOpenTableActionMenus);window.addEventListener('scroll',positionOpenTableActionMenus,true)}
function peerActionsMenu(p){return '<details class="table-action-menu peer-action-menu"><summary>More</summary><div class="table-action-menu-list peer-action-menu-panel"><button data-peer-select="'+attr(p.id)+'">Use</button><button data-peer-test="'+attr(p.id)+'">Test</button><button data-peer-open-metrics="'+attr(p.id)+'">Metrics</button><button data-peer-open-logs="'+attr(p.id)+'">Logs</button><button data-peer-probe="'+attr(p.id)+'"'+disabledAttr('peers.connect')+'>Probe</button><button data-peer-debug="'+attr(p.id)+'"'+disabledAttr('peers.connect')+'>Debug</button><button data-peer-repin="'+attr(p.id)+'"'+disabledAttr('peers.write')+'>Re-pin TLS</button><button data-peer-rotate="'+attr(p.id)+'"'+disabledAttr('peers.write')+'>Rotate pairing</button><button data-peer-edit="'+attr(p.id)+'"'+disabledAttr('peers.write')+'>Edit</button><button data-peer-toggle="'+attr(p.id)+'"'+disabledAttr('peers.write')+'>'+(p.enabled?'Disable':'Enable')+'</button><button class="danger" data-peer-revoke="'+attr(p.id)+'"'+disabledAttr('peers.write')+'>Revoke</button></div></details>'}
function peerVersionText(p){const version=String(p.remoteVersion||'').trim();if(!version)return'-';return /^v/i.test(version)?version:'v'+version}
function peerVersionHtml(p){const version=peerVersionText(p);return '<span class="truncate-cell" title="'+attr(version==='-'?'NordRelay version unknown':'NordRelay '+version)+'">'+esc(version)+'</span>'}
function peerLastSeenHtml(p){if(!p.lastSeenAt)return'-';return '<span title="'+attr(fmtDate(p.lastSeenAt))+'" data-session-age-at="'+attr(p.lastSeenAt)+'">'+esc(fmtSessionAge(p.lastSeenAt))+'</span>'}
function peerRow(p){const selected=state.selectedPeer===p.id?' <span class="chip">selected</span>':'';const trust=p.trustStatus||'trusted';const trustClass=trust==='trusted'?'enabled':trust==='tls-unpinned'?'planned':'disabled';const health=p.remoteStatus||p.lastSeenAt?(p.remoteStatus||'seen')+(p.lastLatencyMs!==undefined?' / '+p.lastLatencyMs+'ms':''):'unchecked';const aliases=Object.entries(p.workspaceAliases||{}).map(([a,w])=>a+'='+w).join(', ');const access='Scopes '+((p.scopes||[]).join(', ')||'-')+' | Agents '+(((p.allowedAgents||[]).join(', '))||'all')+' | Workspaces '+(((p.allowedWorkspaceRoots||[]).join(', '))||'all')+(aliases?' | Aliases '+aliases:'');const identity='Node: '+(p.nodeId||'-')+' | Fingerprint: '+(p.fingerprint||'-')+(p.tlsFingerprint?' | TLS: '+p.tlsFingerprint:'');const details=[identity,p.group?'Group: '+p.group:'',p.direction?'Direction: '+p.direction:'',p.lastCheckedAt?'Checked: '+fmtDate(p.lastCheckedAt):'',p.lastError?'Last error: '+p.lastError:''].filter(Boolean).join(' | ');const history=(p.healthHistory||[]).slice(-5).reverse().map(h=>esc(fmtDate(h.checkedAt)+' | '+h.status+(h.latencyMs!==undefined?' | '+h.latencyMs+'ms':'')+(h.error?' | '+h.error:''))).join('\\n');return '<tr title="'+attr(details+(history?'\\n\\nHealth history:\\n'+history:''))+'">'+peerCell('Name','<span class="truncate-cell" title="'+attr(p.name)+'">'+esc(p.name)+selected+'</span>','primary-cell')+peerCell('Status','<span class="adapter-status '+(p.enabled?'enabled':'disabled')+'">'+(p.enabled?'enabled':'disabled')+'</span>','status-cell')+peerCell('Trust','<span class="adapter-status '+trustClass+'">'+esc(trust)+'</span>','status-cell')+peerCell('URL','<span class="truncate-cell" title="'+attr(p.url||'-')+'">'+esc(short(p.url||'-',120))+'</span>','url-cell')+peerCell('Access','<span class="truncate-cell" title="'+attr(access)+'">'+esc(short(access,180))+'</span>','access-cell')+peerCell('Health','<span class="truncate-cell '+(p.lastError?'error':'')+'" title="'+attr(p.lastError||health)+'">'+esc(short(p.lastError||health,120))+'</span>','health-cell')+peerCell('Version',peerVersionHtml(p),'version-cell')+peerCell('Last seen',peerLastSeenHtml(p),'updated-cell')+peerCell('Actions',peerActionsMenu(p),'actions-cell')+'</tr>'}
async function openPeerDebugDialog(peerId){const report=await api('/api/peers/'+encodeURIComponent(peerId)+'/debug',{local:true});renderPeerDebugDialog(report)}
function renderPeerDebugDialog(report){const title='Peer debug'+(report.peer?.name?': '+report.peer.name:'');adminDialog(title,peerDebugHtml(report),async()=>{}, {submitText:'Close',reloadAccess:false});bindPeerDebugDialog(report)}
function peerDebugHtml(report){const summary=report.summary||{};const status=summary.status||'unknown';return '<div class="peer-debug-dialog" data-peer-debug-id="'+attr(report.peer?.id||'')+'"><div class="peer-debug-summary"><strong>'+esc(report.peer?.name||'Peer')+' <span class="adapter-status '+peerDebugStatusClass(status)+'">'+esc(status)+'</span></strong><small>'+esc(summary.primaryIssue||'No primary issue detected.')+'</small>'+(summary.remediation?'<small>'+esc(summary.remediation)+'</small>':'')+'</div><div class="section-tabs peer-debug-tabs" role="tablist"><button type="button" class="active" data-peer-debug-tab="summary">Summary</button><button type="button" data-peer-debug-tab="connectivity">Connectivity</button><button type="button" data-peer-debug-tab="access">Access</button><button type="button" data-peer-debug-tab="routes">Routes</button><button type="button" data-peer-debug-tab="events">Events</button><button type="button" data-peer-debug-tab="history">History</button><button type="button" data-peer-debug-tab="repair">Repair</button></div>'+peerDebugPanel('summary',true,peerDebugSummaryTable(report))+peerDebugPanel('connectivity',false,peerDebugChecksTable(report.checks||[],['configured','enabled','transport','tls-pin','endpoint-health','endpoint-identity','rpc-ping','relay-queue']))+peerDebugPanel('access',false,peerDebugAccessTable(report.access))+peerDebugPanel('routes',false,peerDebugChecksTable(report.checks||[],['route-bootstrap','route-sessions','route-active-sessions','route-diagnostics','route-logs']))+peerDebugPanel('events',false,peerDebugChecksTable(report.checks||[],['events']))+peerDebugPanel('history',false,peerDebugHistoryTable(report.healthHistory||[]))+peerDebugPanel('repair',false,peerDebugRepairHtml(report))+'</div>'}
function peerDebugPanel(name,active,body){return '<div class="peer-debug-panel '+(active?'active':'')+'" data-peer-debug-panel="'+attr(name)+'">'+body+'</div>'}
function peerDebugStatusClass(status){return status==='ok'?'enabled':status==='error'?'disabled':'planned'}
function peerDebugSummaryTable(report){const p=report.peer||{};const s=report.summary||{};const rows=[['Status',s.status||'-'],['Checks',(s.ok||0)+' ok / '+(s.warnings||0)+' warn / '+(s.errors||0)+' error / '+(s.skipped||0)+' skipped'],['Node',p.nodeId||'-'],['Direction',p.direction||'-'],['URL',p.url||'-'],['TLS fingerprint',p.tlsFingerprint||'-'],['Remote version',p.remoteVersion||'-'],['Last error',p.lastError||'-']];return peerDebugKeyValueTable(rows)+'<div class="row peer-heading-actions"><button type="button" data-peer-debug-probe="'+attr(p.id||'')+'"'+disabledAttr('peers.connect')+'>Run full probe</button></div>'}
function peerDebugKeyValueTable(rows){return '<div class="data-table-wrap"><table class="data-table peer-debug-kv-table"><thead><tr><th>Metric</th><th>Value</th></tr></thead><tbody>'+rows.map(r=>'<tr>'+peerCell('Metric',esc(r[0]),'primary-cell')+peerCell('Value','<span class="truncate-cell" title="'+attr(r[1]??'-')+'">'+esc(r[1]??'-')+'</span>')+'</tr>').join('')+'</tbody></table></div>'}
function peerDebugChecksTable(checks,ids){const set=new Set(ids);const rows=(checks||[]).filter(c=>set.has(c.id));if(!rows.length)return uiEmpty('No checks recorded. Run full probe to collect live diagnostics.');return '<div class="data-table-wrap"><table class="data-table peer-debug-checks-table"><thead><tr><th>Check</th><th>Status</th><th>Code</th><th>Latency</th><th>Detail</th><th>Fix</th></tr></thead><tbody>'+rows.map(peerDebugCheckRow).join('')+'</tbody></table></div>'}
function peerDebugCheckRow(c){return '<tr>'+peerCell('Check','<span class="truncate-cell" title="'+attr(c.label||'')+'">'+esc(c.label||'-')+'</span>','primary-cell')+peerCell('Status','<span class="adapter-status '+peerDebugStatusClass(c.status)+'">'+esc(c.status||'-')+'</span>','status-cell')+peerCell('Code','<span class="truncate-cell" title="'+attr(c.code||'-')+'">'+esc(c.code||'-')+'</span>')+peerCell('Latency',esc(c.latencyMs!==undefined?c.latencyMs+'ms':'-'))+peerCell('Detail','<span class="truncate-cell" title="'+attr(c.detail||'')+'">'+esc(short(c.detail||'-',220))+'</span>')+peerCell('Fix','<span class="truncate-cell" title="'+attr(c.remediation||'')+'">'+esc(short(c.remediation||'-',220))+'</span>')+'</tr>'}
function peerDebugAccessTable(access){if(!access)return uiEmpty('No access report available.');const rows=access.checks||[];if(!rows.length)return uiEmpty('No access checks.');return '<p>'+esc(access.summary||'')+'</p><div class="data-table-wrap"><table class="data-table peer-debug-access-table"><thead><tr><th>Feature</th><th>Allowed</th><th>Permission</th><th>User</th><th>Peer</th><th>Reason</th><th>Fix</th></tr></thead><tbody>'+rows.map(a=>'<tr>'+peerCell('Feature','<span class="truncate-cell" title="'+attr(a.label||'')+'">'+esc(a.label||'-')+'</span>','primary-cell')+peerCell('Allowed','<span class="adapter-status '+(a.allowed?'enabled':'disabled')+'">'+esc(a.allowed?'yes':'no')+'</span>','status-cell')+peerCell('Permission',esc(a.requiredPermission||'-'))+peerCell('User',esc(a.localAllowed===null?'-':a.localAllowed?'yes':'no'))+peerCell('Peer',esc(a.peerAllowed===null?'-':a.peerAllowed?'yes':'no'))+peerCell('Reason','<span class="truncate-cell" title="'+attr(a.reason||'')+'">'+esc(short(a.reason||'-',220))+'</span>')+peerCell('Fix','<span class="truncate-cell" title="'+attr(a.fix||'')+'">'+esc(short(a.fix||'-',220))+'</span>')+'</tr>').join('')+'</tbody></table></div>'}
function peerDebugHistoryTable(history){const rows=(history||[]).slice().reverse().slice(0,100);if(!rows.length)return uiEmpty('No peer health history yet.');return '<div class="data-table-wrap"><table class="data-table peer-debug-history-table"><thead><tr><th>Time</th><th>Status</th><th>Check</th><th>Code</th><th>Latency</th><th>Detail</th></tr></thead><tbody>'+rows.map(h=>'<tr>'+peerCell('Time','<span title="'+attr(fmtDate(h.checkedAt))+'">'+esc(h.checkedAt?fmtSessionAge(h.checkedAt):'-')+'</span>','updated-cell')+peerCell('Status','<span class="adapter-status '+(h.status==='online'?'enabled':'disabled')+'">'+esc(h.status||'-')+'</span>','status-cell')+peerCell('Check',esc(h.check||'-'))+peerCell('Code','<span class="truncate-cell" title="'+attr(h.code||'-')+'">'+esc(h.code||'-')+'</span>')+peerCell('Latency',esc(h.latencyMs!==undefined?h.latencyMs+'ms':'-'))+peerCell('Detail','<span class="truncate-cell" title="'+attr(h.error||h.detail||'')+'">'+esc(short(h.error||h.detail||'-',240))+'</span>')+'</tr>').join('')+'</tbody></table></div>'}
function peerDebugRepairHtml(report){const actions=report.repairActions||[];if(!actions.length)return uiEmpty('No repair actions are available for this peer.');const labels={'repin-tls':'Re-pin TLS','clear-error':'Clear error','enable':'Enable peer','disable':'Disable peer','retry-relay':'Retry relay','drain-expired':'Drain expired relay','rotate-pairing':'Rotate pairing'};return '<div class="data-table-wrap"><table class="data-table peer-debug-repair-table"><thead><tr><th>Action</th><th>Description</th><th class="actions-heading">Run</th></tr></thead><tbody>'+actions.map(a=>'<tr>'+peerCell('Action',esc(labels[a]||a),'primary-cell')+peerCell('Description','<span class="truncate-cell" title="'+attr(peerRepairDescription(a))+'">'+esc(peerRepairDescription(a))+'</span>')+peerCell('Run','<div class="data-table-actions"><button type="button" '+(a==='disable'||a==='drain-expired'?'class="danger"':'class="secondary"')+' data-peer-repair="'+attr(a)+'" data-peer-id="'+attr(report.peer?.id||'')+'"'+disabledAttr('peers.write')+'>'+esc(labels[a]||a)+'</button></div>','actions-cell')+'</tr>').join('')+'</tbody></table></div>'}
function peerRepairDescription(action){return { 'repin-tls':'Verify the stored peer identity and update the pinned TLS fingerprint.', 'clear-error':'Clear the retained last error after you fixed the underlying problem.', enable:'Enable this peer for routing and remote calls.', disable:'Disable this peer without deleting pairing data.', 'retry-relay':'Move stale relay requests back to the pending queue.', 'drain-expired':'Remove expired relay requests from the relay queue.', 'rotate-pairing':'Create a new one-time pairing invite for this peer.' }[action]||action}
function bindPeerDebugDialog(report){const root=document.getElementById('adminDialogBody');root.querySelectorAll('[data-peer-debug-tab]').forEach(b=>b.onclick=()=>{const tab=b.dataset.peerDebugTab;root.querySelectorAll('[data-peer-debug-tab]').forEach(x=>x.classList.toggle('active',x.dataset.peerDebugTab===tab));root.querySelectorAll('[data-peer-debug-panel]').forEach(x=>x.classList.toggle('active',x.dataset.peerDebugPanel===tab))});const probe=root.querySelector('[data-peer-debug-probe]');if(probe)probe.onclick=()=>safe(async()=>{probe.disabled=true;probe.textContent='Running probe...';const next=await api('/api/peers/'+encodeURIComponent(probe.dataset.peerDebugProbe)+'/debug/probe',{method:'POST',body:JSON.stringify({}),local:true});document.getElementById('adminDialogBody').innerHTML=peerDebugHtml(next);bindPeerDebugDialog(next);toast('Peer debug probe completed')});root.querySelectorAll('[data-peer-repair]').forEach(b=>b.onclick=()=>safe(async()=>{if(!confirm('Run peer repair action '+b.dataset.peerRepair+'?'))return;const result=await api('/api/peers/'+encodeURIComponent(b.dataset.peerId)+'/repair',{method:'POST',body:JSON.stringify({action:b.dataset.peerRepair}),local:true});document.getElementById('adminDialogBody').innerHTML=peerDebugHtml(result.report||report);bindPeerDebugDialog(result.report||report);if(result.result?.command)toast('Rotation invite created. Command: '+result.result.command,{duration:10000});else toast('Peer repair action completed');await loadPeers()}) )}
function openPeerDialog(p){const aliases=Object.entries(p.workspaceAliases||{}).map(([a,w])=>a+'='+w).join(', ');adminDialog('Edit peer','<label>Name<input id="dlgPeerName" value="'+attr(p.name||'')+'"></label><label>Group<input id="dlgPeerGroup" value="'+attr(p.group||'')+'" placeholder="LAN, Servers, Workstations"></label><label>URL<input id="dlgPeerUrl" value="'+attr(p.url||'')+'"></label><label class="checkbox"><input id="dlgPeerEnabled" type="checkbox" '+(p.enabled?'checked':'')+'> Enabled</label><label class="full-span">Scopes<input id="dlgPeerScopes" value="'+attr((p.scopes||[]).join(', '))+'"></label><label class="full-span">Allowed agents<input id="dlgPeerAgents" value="'+attr((p.allowedAgents||[]).join(', '))+'"></label><label class="full-span">Allowed workspace roots<input id="dlgPeerWorkspaces" value="'+attr((p.allowedWorkspaceRoots||[]).join(', '))+'"></label><label class="full-span">Workspace aliases<input id="dlgPeerAliases" placeholder="project=/srv/project, demo=/home/me/demo" value="'+attr(aliases)+'"></label>',async()=>{await api('/api/peers/'+encodeURIComponent(p.id),{method:'PATCH',body:JSON.stringify({name:val('dlgPeerName'),group:val('dlgPeerGroup'),url:val('dlgPeerUrl'),enabled:document.getElementById('dlgPeerEnabled').checked,scopes:csvToList(val('dlgPeerScopes')),allowedAgents:csvToList(val('dlgPeerAgents')),allowedWorkspaceRoots:csvToList(val('dlgPeerWorkspaces')),workspaceAliases:aliasMap(val('dlgPeerAliases'))}),local:true});toast('Peer updated');await loadPeers()})}
function openPeerInviteDialog(){const warnings=state.peers?.readiness?.warnings||[];const warningHtml=peerWarningsHtml(warnings,'Pairing warning')+(warnings.length?'<small class="full-span">The invite can still be created, but pairing may fail until the peer endpoint is reachable.</small>':'');adminDialog('Create peer invite',warningHtml+'<label>Name<input id="dlgPeerInviteName" value="NordRelay peer"></label><label>Group<input id="dlgPeerInviteGroup" placeholder="LAN, Servers, Workstations"></label><label>Expires minutes<input id="dlgPeerInviteExpires" type="number" value="10" min="1" max="1440"></label><label class="full-span">Scopes<input id="dlgPeerInviteScopes" value="inspect, sessions.read, sessions.write, prompt.send, prompt.abort, queue.read, queue.write, files.read, files.write, diagnostics.read, logs.read"></label><label class="full-span">Allowed agents<input id="dlgPeerInviteAgents" value="codex, pi, hermes, openclaw, claude-code"></label><label class="full-span">Allowed workspace roots<input id="dlgPeerInviteWorkspaces" placeholder="empty means all"></label><label class="full-span">Workspace aliases<input id="dlgPeerInviteAliases" placeholder="project=/srv/project, demo=/home/me/demo"></label>',async()=>{const r=await api('/api/peers/invite',{method:'POST',body:JSON.stringify({name:val('dlgPeerInviteName'),group:val('dlgPeerInviteGroup')||undefined,expiresMinutes:Number(val('dlgPeerInviteExpires')||10),scopes:csvToList(val('dlgPeerInviteScopes')),allowedAgents:csvToList(val('dlgPeerInviteAgents')),allowedWorkspaceRoots:csvToList(val('dlgPeerInviteWorkspaces')),workspaceAliases:aliasMap(val('dlgPeerInviteAliases'))}),local:true});if(r.invitation?.id)state.peerInviteSecrets[r.invitation.id]={code:r.code||'',command:r.command||''};toast('Peer invite created. Pairing details are shown under Open invitations.',{duration:8000});await loadPeers()});document.getElementById('adminDialogSubmit').textContent=warnings.length?'Create invite anyway':'Create invite'}
function aliasMap(text){return Object.fromEntries((text||'').split(',').map(item=>item.split('=',2).map(part=>part.trim())).filter(([a,w])=>a&&w))}
function bindPeerButtons(){bindTableActionMenus(document.getElementById('peersList')||document);const reloadTopology=document.getElementById('reloadPeerTopologyBtn');if(reloadTopology)reloadTopology.onclick=()=>safe(loadPeers);const reloadRelay=document.getElementById('reloadPeerRelayBtn');if(reloadRelay)reloadRelay.onclick=()=>safe(loadPeers);const retryRelay=document.getElementById('retryPeerRelayBtn');if(retryRelay)retryRelay.onclick=()=>safe(async()=>{if(!can('peers.write')){toast('Permission required: peers.write');return}const r=await api('/api/peers/relay',{method:'POST',local:true,body:JSON.stringify({action:'retry'})});state.peerRelay=r;document.getElementById('peerRelay').innerHTML=renderPeerRelay(r);bindUiCopyButtons(document.getElementById('peerRelay'));bindPeerButtons();toast('Relay retry moved '+(r.result?.moved??0)+' request(s)')});const drainRelay=document.getElementById('drainPeerRelayBtn');if(drainRelay)drainRelay.onclick=()=>safe(async()=>{if(!can('peers.write')){toast('Permission required: peers.write');return}const r=await api('/api/peers/relay',{method:'POST',local:true,body:JSON.stringify({action:'drain-expired'})});state.peerRelay=r;document.getElementById('peerRelay').innerHTML=renderPeerRelay(r);bindUiCopyButtons(document.getElementById('peerRelay'));bindPeerButtons();toast('Expired relay requests drained')});document.querySelectorAll('[data-peer-relay-cancel]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('peers.write')){toast('Permission required: peers.write');return}if(confirm('Cancel this relay request?')){const r=await api('/api/peers/relay',{method:'POST',local:true,body:JSON.stringify({action:'cancel',peerId:b.dataset.peerId,id:b.dataset.peerRelayCancel})});state.peerRelay=r;document.getElementById('peerRelay').innerHTML=renderPeerRelay(r);bindUiCopyButtons(document.getElementById('peerRelay'));bindPeerButtons();toast(r.result?.removed?'Relay request cancelled':'Relay request not found')}}));document.querySelectorAll('[data-peer-select]').forEach(b=>b.onclick=()=>safe(async()=>{state.selectedPeer=b.dataset.peerSelect||'local';localStorage.setItem('nordrelayPeerTarget',state.selectedPeer);connectEvents();await loadBootstrap();toast('Peer target selected')}));document.querySelectorAll('[data-peer-test]').forEach(b=>b.onclick=()=>safe(async()=>{const r=await api('/api/peers/'+encodeURIComponent(b.dataset.peerTest)+'/health',{local:true});toast('Peer reachable: '+(r.data?.version?'v'+r.data.version:'ok'),{duration:6000});loadPeers()}));document.querySelectorAll('[data-peer-open-metrics]').forEach(b=>b.onclick=()=>safe(async()=>{state.selectedPeer=b.dataset.peerOpenMetrics||'local';localStorage.setItem('nordrelayPeerTarget',state.selectedPeer);connectEvents();await loadBootstrap();page('metrics')}));document.querySelectorAll('[data-peer-open-logs]').forEach(b=>b.onclick=()=>safe(async()=>{state.selectedPeer=b.dataset.peerOpenLogs||'local';localStorage.setItem('nordrelayPeerTarget',state.selectedPeer);connectEvents();await loadBootstrap();page('logs')}));const localProbe=document.getElementById('checkPeerReachabilityBtn');if(localProbe)localProbe.onclick=()=>safe(async()=>{if(!can('peers.connect')){toast('Permission required: peers.connect');return}state.peerProbeResult=await api('/api/peers/probe',{method:'POST',body:JSON.stringify({}),local:true});document.getElementById('peerProbeResult').innerHTML=peerProbeResultHtml(state.peerProbeResult);toast(state.peerProbeResult.probe?.ok?'Peer endpoint reachable':'Peer endpoint not reachable',{duration:7000})});document.querySelectorAll('[data-peer-probe]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('peers.connect')){toast('Permission required: peers.connect');return}const p=(state.peers?.peers||[]).find(x=>x.id===b.dataset.peerProbe);state.peerProbeResult=await api('/api/peers/probe',{method:'POST',body:JSON.stringify({peerId:b.dataset.peerProbe}),local:true});state.peerProbeResult.peerName=p?.name;document.getElementById('peerProbeResult').innerHTML=peerProbeResultHtml(state.peerProbeResult);toast(state.peerProbeResult.probe?.ok?'Remote peer can reach this node':'Remote peer cannot reach this node',{duration:8000})}));document.querySelectorAll('[data-peer-edit]').forEach(b=>b.onclick=()=>{const p=(state.peers?.peers||[]).find(x=>x.id===b.dataset.peerEdit);if(p)openPeerDialog(p)});document.querySelectorAll('[data-peer-toggle]').forEach(b=>b.onclick=()=>safe(async()=>{const p=(state.peers?.peers||[]).find(x=>x.id===b.dataset.peerToggle);if(!p)return;await api('/api/peers/'+encodeURIComponent(p.id),{method:'PATCH',body:JSON.stringify({enabled:!p.enabled}),local:true});toast('Peer updated');loadPeers()}));document.querySelectorAll('[data-peer-revoke]').forEach(b=>b.onclick=()=>safe(async()=>{if(confirm('Revoke this peer?')){await api('/api/peers/'+encodeURIComponent(b.dataset.peerRevoke),{method:'DELETE',local:true});if(state.selectedPeer===b.dataset.peerRevoke){state.selectedPeer='local';localStorage.setItem('nordrelayPeerTarget','local')}toast('Peer revoked');loadPeers()}}));document.querySelectorAll('[data-peer-invite-copy]').forEach(b=>b.onclick=()=>copyText(b.dataset.peerInviteCopy||'',b.dataset.peerInviteCopyLabel||'Copied'));document.querySelectorAll('[data-peer-invite-delete]').forEach(b=>b.onclick=()=>safe(async()=>{if(confirm('Delete this peer invitation?')){await api('/api/peers/invitations/'+encodeURIComponent(b.dataset.peerInviteDelete),{method:'DELETE',local:true});delete state.peerInviteSecrets[b.dataset.peerInviteDelete];toast('Peer invitation deleted');loadPeers()}}))}
